mapper.select:
SELECT a.admin_id, a.login_id, a.admin_nm, a.dept_nm, a.status_cd, c.code_nm AS status_nm,
       a.last_login_dt, a.reg_dt
FROM tb_admin a
LEFT JOIN tb_code c ON c.group_cd = 'ADMIN_STATUS' AND c.code = a.status_cd

ORDER BY ${q.orderBy}
LIMIT #{q.size} OFFSET #{offset}

mapper.update:
UPDATE tb_admin
SET password = #{password}, pwd_temp_yn = 'Y', mod_id = #{modId}, mod_dt = now()
WHERE admin_id = #{adminId}

mapper.select:
SELECT h.reg_dt, h.result_cd, c.code_nm AS result_nm, h.auth_type_cd, h.ip_addr
FROM tb_admin_login_hist h
LEFT JOIN tb_code c ON c.group_cd = 'LOGIN_RESULT' AND c.code = h.result_cd
WHERE h.admin_id = #{adminId}
ORDER BY h.reg_dt DESC, h.hist_id DESC
LIMIT #{limit}
